#[path="native-codec.rs"]mod codec;
use std::io::{self,BufRead};
fn main(){for line in io::stdin().lock().lines(){let r:serde_json::Value=serde_json::from_str(&line.unwrap()).unwrap();let h=match r["mode"].as_str().unwrap(){"Deflate"=>codec::Header::Zlib,"DeflateRaw"=>codec::Header::Raw,"Gzip"=>codec::Header::Gzip,_=>panic!()};let mut c=codec::Compressor::new(h,r["level"].as_i64().unwrap() as i32).unwrap();let mut rows=Vec::new();for part in r["chunks"].as_array().unwrap(){let input=part["bytes"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as u8).collect::<Vec<_>>();let f=match part["flush"].as_u64().unwrap(){0=>codec::Flush::None,1=>codec::Flush::Partial,2=>codec::Flush::Sync,3=>codec::Flush::Full,4=>codec::Flush::Finish,5=>codec::Flush::Block,_=>panic!()};let out=c.process(&input,f).unwrap();rows.push(serde_json::json!({"bytes":out.bytes,"consumed":out.consumed}));}println!("{}",serde_json::json!(rows));}}
